# -*- coding: utf-8 -*-
"""
قانون مدنی – کتاب اول: در اموال (مواد ۱ تا ۱۱۹)
نسخه نهایی با آخرین اصلاحات تا ۱۴۰۳
منبع: متن رسمی از سامانه ملی قوانین و مقررات
"""

BOOK1_ARTICLES = [
    # ---------- باب اول: در انتشار و اجرای قوانین مصوب ----------
    (1, "اعمال قانون از طرف مقنن نسبت به آنچه که قبل از وضع آن واقع شده مؤثر نیست مگر آن‌که در خود قانون، ترتیب دیگری مقرر شده باشد."),
    (2, "قوانین پانزده روز پس از انتشار در سراسر ایران لازم‌الاجرا است مگر آن‌که در خود قانون ترتیب خاصی برای موقع اجرا مقرر شده باشد."),
    (3, "انتشار قوانین باید در روزنامه رسمی به عمل آید."),
    (4, "اثر قانون نسبت به آتیه است و قانون نسبت به ما قبل خود اثر ندارد مگر این‌که در خود قانون، ترتیب دیگری مقرر شده باشد."),
    (5, "کلیه سکنه ایران اعم از اتباع داخله و خارجه مطیع قوانین ایران خواهند بود مگر در مواردی که قانون استثنا کرده باشد."),
    (6, "قوانین مربوط به احوال شخصیه در مورد کلیه اتباع ایران ولو این‌که مقیم در خارجه باشند مجری خواهد بود."),
    (7, "اتباع خارجه مقیم در ایران از حیث مسائل مربوط به احوال شخصیه و اهلیت خود و همچنین از حیث حقوق ارثیه در حدود قراردادها مطیع قوانین و مقررات دولت متبوع خود خواهند بود."),
    (8, "اموال غیرمنقوله از قبیل اراضی و ابنیه در هر نقطه که واقع باشد تابع قوانین ایران می‌باشد."),
    (9, "اسناد از حیث طرز تنظیم تابع قوانین مکان تنظیم خود می‌باشند."),
    (10, "قراردادهای خصوصی نسبت به کسانی که آن را منعقد نموده‌اند در صورتی که مخالف صریح قانون و موازین اسلامی نباشد و متضمن ضرر به شخص ثالث و خلاف نظم عمومی و اخلاق حسنه نباشد نافذ است."),

    # ---------- باب دوم: در اموال ----------
    (11, "اموال یا به ملکیت اشخاص تعلق دارد یا آن‌که به هیچ مالکی اختصاص نداشته و برای مصالح عامه اختصاص داده شده است."),
    (12, "اموال بر دو قسم است: منقول و غیرمنقول."),
    (13, "اراضی و ابنیه و آسیا و هر چه که در بنا منصوب بوده و به‌صورتی جزء بنا محسوب باشد غیرمنقول است. همچنین است لوله‌های آب و قنوات و تلمبه‌های ثابت و امثال آن."),
    (14, "آسیا و حمام و کارخانه و مانند این‌ها که در زمین به کار گذاشته شده غیرمنقول است به‌طوری‌که نمی‌توان آن را بدون خرابی از محل خود منتقل کرد."),
    (15, "آینه و پرده نقاشی و مجسمه و امثال آن‌ها در صورتی که در بنا یا زمین به‌کار رفته باشد به‌نحوی که عرفاً جزء بنا محسوب شود غیرمنقول است."),
    (16, "میوه‌هایی که هنوز چیده نشده و هم‌چنین حاصلی که از درخت نیفتاده است غیرمنقول است."),
    (17, "حیوانات و اشیایی که مالک آن را برای عمل زراعت اختصاص داده باشد از قبیل گاو و گاومیش و ماشین و اسباب و آلات و اثاثیه و بذر و غیره و به‌طور کلی هر مال منقول که برای استفاده از عمل زراعت لازم و مالک آن را به‌این امر تخصیص داده باشد از جهت صلاحیت محاکم و توقیف اموال جزء ملک محسوب و در حکم مال غیرمنقول است."),
    (18, "کشتی‌های کوچک و بزرگ و قایق‌ها و آسیاها و حمام‌هایی که در روی رودخانه و دریاها ساخته می‌شود و می‌توانند آن‌ها را حرکت بدهند و کلیه کارخانه‌هایی که در روی شناور ساخته شده و آن را متحرک می‌نامند منقول است ولی توقیف این‌قبیل اموال در خود همان آب‌ها ممکن است."),
    (19, "اشخاصی که در خارجه اقامت دارند از حیث رسوم‌الاجرا و اموری که راجعه به اموال غیرمنقوله است که در ایران واقع شده مطیع قوانین ایران می‌باشند."),
    (20, "کلیه اموالی که غیرمنقول است تابع قانون دولت متبوع مالک نیست مگر اموالی که در خارجه واقع شده و برای آن‌ها مطابق قوانین محل وقوع رفتار می‌شود."),
    (21, "اموال از جهت اینکه قابل تملک خصوصی هستند یا نه بر سه قسم‌اند: ۱) اموال عمومی ۲) اموال دولت ۳) اموال خصوصی."),
    (22, "اموال غیرمنقوله که مالک خاص ندارد متعلق به دولت است و تصرف در آن‌ها تابع مقررات خاصه دولت است."),
    (23, "اموال غیرمنقوله مباحه عبارت از زمین‌هایی است که از عهد قدیم بدون مانع و بلامعارض مورد استفاده عموم بوده و به ملکیت کسی در نیامده باشد."),
    (24, "هیچ‌کس نمی‌تواند از طرق و شوارع عامه و کوچه‌هایی که انتهای آن‌ها مسدود نیست تملک خصوصی نماید."),
    (25, "هیچ‌کس نمی‌تواند از اموالی که مورد استفاده عموم است و پل‌ها و کاروان‌سراها و آب‌انبارهای عمومی و مدارس و امثال آن‌ها تملک خصوصی نماید."),
    (26, "اموالی که در تصرف مسلمین است و سند مالکیت آن‌ها مخالف با شرع نباشد محترم است."),
    (27, "اموالی که در ملکیت کسی نبوده و مباحات اصلی محسوب می‌شود مانند اراضی موات و آب‌های مباحه و... مطابق قوانین مخصوصه به خود آن‌ها به ملکیت درمی‌آید."),
    (28, "اموال خصوصی که تحت ید مسلمان باشد و همچنین اموالی که مسلمانان از کفار به دست آورده‌اند محترم و مالک آن‌ها بر اساس اصل مصونیت مال افراد شناخته می‌شود."),

    # ---------- باب سوم: در تملک املاک مباحه و اموال متروک ----------
    (29, "اراضی موات که بدون سابقه احیا رها شده و هیچ‌گونه زراعت و درختکاری و بنایی در آن‌ها وجود نداشته باشد به هر کس که آن را احیا نماید تعلق می‌گیرد."),
    (30, "هر مالکی نسبت به مایملک خود حق همه‌گونه تصرف و انتفاع دارد مگر در مواردی که قانون استثنا کرده باشد."),
    (31, "هیچ مالی را از تصرف صاحبش نمی‌توان بیرون کرد مگر به حکم قانون."),
    (32, "همه افراد ملت از حقوق مدنی متمتع هستند و هیچ‌کس را نمی‌توان از حقوق مدنی محروم کرد."),
    (33, "مالکیت به‌وسیله احیای اراضی موات و حیازت اشیاء مباحه تحصیل می‌شود."),
    (34, "احیاء عبارت است از عملی که به‌وسیله آن زمین موات را به صورت زمینی که قابل زراعت و استفاده باشد درآورند مانند آبیاری یا زهکشی و بذرکاری و درختکاری و بناسازی."),
    (35, "هرگاه شخصی زمین موات را به قصد تملک احیا کند مالک آن می‌شود."),
    (36, "حیازت عبارت است از تسلط بر چیزی به قصد تملک."),
    (37, "اشیاء مباحه یعنی چیزهایی که می‌تواند مورد تملک خصوصی واقع شود و در حال حاضر مالک مخصوص نداشته باشد."),
    (38, "صید ماهی و حیوانات مباح دیگر و گرفتن پرندگان و شکار حیوانات وحشی موجب تملک است."),
    (39, "اگر دو نفر با هم چیزی را حیازت نمایند هر دو شریک آن می‌باشند."),
    (40, "مالکیت عبارت است از حق مطلق نسبت به شیئی به‌طوری‌که صاحب مال می‌تواند در آن هرگونه تصرفی که مایل است بنماید مگر در مواردی که قانون منع کرده باشد."),
    (41, "هر مال باید مالک داشته باشد."),
    (42, "وقتی‌که مال بدون مالک باشد به دولت تعلق می‌گیرد."),

    # ---------- باب چهارم: در حقوق ارتفاقی و ... (در استفاده املاک) ----------
    (43, "مالک حق دارد به‌وسیله نهرهای روباز آب را از املاک مجاور عبور دهد مشروط بر این‌که خسارت وارده را به مالک مجاور بدهد."),
    (44, "مالک ملک می‌تواند از هوای بالای ملک همسایه تا حدی که برای ساختمان لازم است استفاده کند مگر آن‌که ممانعت صریح مالک همسایه وجود داشته باشد."),
    (45, "کسی که در ملک خود حق مجرا یا راهی به ملک دیگری دارد نسبت به آن حق ارتفاق دارد."),
    (46, "حق ارتفاق ممکن است به‌وسیله قرارداد و یا به‌وسیله قرارداد ضمنی ایجاد شود."),
    (47, "حق ارتفاق ممکن است به‌وسیله عدم استعمال در مدت مرور زمان از بین برود."),
    (48, "حق ارتفاق ممکن است به سبب از بین رفتن محلی که حق در آن قرار دارد ساقط شود."),
    (49, "کسی که در دیوار همسایه خود سرتیر یا دودکش یا مانند آن را قرار می‌دهد باید خسارت صاحب دیوار را بپردازد."),
    (50, "هرگاه درخت یا بنایی در ملک کسی قرار گرفته باشد و شاخه یا ریشه آن در ملک مجاور وارد شود صاحب ملک مجاور می‌تواند از ورود آن جلوگیری کند و در صورتی‌که خسارت وارد شده باشد مطالبه خسارت نماید."),
    (51, "آب‌های جاری در نهرهای طبیعی متعلق به عموم است و همه کس می‌تواند از آن به مقدار متعارف استفاده کند مگر در مواردی که به‌موجب قانون حقوق خاصی برای کسی ثابت شده باشد."),
    (52, "کسی که نهر یا چشمه‌ای در ملک خود دارد می‌تواند آن را در هر راهی که مایل است مصرف کند مگر این‌که به‌موجب قانون یا قرارداد حقی برای دیگری ثابت شده باشد."),
    (53, "چاه و قناتی که کسی در ملک خود حفر می‌کند متعلق به خود اوست."),
    (54, "هر گاه کسی در زمین مباح چشمه یا چاهی احداث کند مالک آن می‌شود."),
    (55, "کسی که از آب نهر عمومی استفاده می‌کند باید راه عبور آب را از ملک خود باز بگذارد."),
    (56, "اگر آب نهر از ملک کسی عبور کند مالک نمی‌تواند از عبور آن جلوگیری نماید مگر این‌که خسارت زیادی به او وارد آید."),
    (57, "هر کس حق دارد که از زمین و هوای بالای ملک خود به هر ارتفاعی که می‌خواهد استفاده کند و می‌تواند از دخول و تصرف دیگران جلوگیری کند."),
    (58, "صاحب ملک می‌تواند مانع شود از آن‌که کسی بدون اذن او وارد ملک وی شود مگر در مواردی که قانون اجازه داده باشد."),
    (59, "هرگاه برای تعمیر یا ساختن بنا ورود به ملک همسایه لازم باشد صاحب ملک باید اجازه ورود بدهد."),
    (60, "کسی که در کنار املاک دیگری قرار دارد نمی‌تواند عملی انجام دهد که از عهده آن خسارت هنگفتی به همسایه وارد آید مانند آن‌که دودکش یا چاه توالت خود را در محلی قرار دهد که هوای همسایه را آلوده سازد."),
    (61, "همچنین کسی نمی‌تواند چاه یا کاریز چنان حفر کند که آب چاه همسایه را خشک کند یا ضرر دیگری به او وارد سازد."),
    (62, "برای جلوگیری از خسارت وارده بر همسایه محکمه می‌تواند صاحب ملک را به عملی مجبور یا از عملی منع کند."),
    (63, "حق عبادت و رفت و آمد در املاکی که مسدود و محاط در املاک دیگر است راهدار نامیده می‌شود."),
    (64, "اگر ملکی به‌کلی در میان املاک دیگران محصور و راه عبور به طریق عامه نداشته باشد صاحب آن حق دارد از یکی از املاک مجاور به مقدار لزوم برای عبور و مرور استفاده کند."),
    (65, "انتخاب محلی که باید از آن عبور شود به عهده کسی است که از ملک او عبور می‌شود."),
    (66, "حق راهداری در ملک تحتانی بر ملک فوقانی جهت عبور دودکش یا ناودان از قبیل حق ارتفاق است."),
    (67, "حق ارتفاق نسبت به املاک ممکن است به‌صورت دائمی یا موقت باشد."),

    # ---------- باب پنجم: در اسباب تملک (کلیات) ----------
    (68, "اسباب تملک عبارتند از: ۱) احیاء اراضی موات و حیازت اشیاء مباحه، ۲) عقود و تعهدات، ۳) اخذ به شفعه، ۴) ارث."),
    (69, "به وسیله عقود و تعهدات یک نفر می‌تواند در مقابل یک یا چند نفر دیگر ملتزم به امری گردد."),

    # ---------- باب ششم: در اسباب تملک – دفتر اول: در قراردادها و تعهدات ----------
    (70, "قراردادها بین طرفین و قائم‌مقام آن‌ها لازم‌الاتباع است."),
    (71, "عقودی که بر طبق قانون واقع شده باشد نسبت به متعاملین و قائم‌مقام آن‌ها لازم‌الاتباع می‌باشد مگر این‌که به رضای طرفین اقاله و یا به علت قانونی فسخ گردد."),
    (72, "برای این‌که قراردادی نافذ باشد باید طرفین اهلیت داشته باشند."),
    (73, "اهلیت برای معامله عبارت است از بلوغ و عقل و رشید."),
    (74, "طفل غیررشید می‌تواند در امور مالی فقط با اجازه ولی و در حدود قوانین مربوطه دخالت کند."),
    (75, "مجنون هیچ‌گونه معامله مالی نمی‌تواند بکند و سفیه که توانایی اداره امور مالی خود را ندارد معاملاتش با اذن ولی نافذ است."),
    (76, "اشخاص ذیل محجورند: ۱) اطفال کمتر از سن بلوغ، ۲) اشخاص غیررشید، ۳) مجانین."),
    (77, "برای اینکه متعاملین اهل محسوب شوند باید بالغ و عاقل و رشید باشند."),
    (78, "انسان می‌تواند هرگونه صلحی در مورد اموال خود بنماید مگر این‌که قانون منع کرده باشد."),
    (79, "مجوزاتی که در این قانون ذکر شده است مانع از آن نخواهد بود که انسان بر مال خود هر نوع حقی را که می‌خواهد به دیگری منتقل کند."),
    (80, "کسی که معامله می‌کند آن معامله برای خودش محسوب است مگر این‌که در موقع انعقاد خلاف آن را تصریح کند."),
    (81, "برای صحت هر معامله شرایط ذیل اساسی است: ۱) قصد طرفین و رضای آن‌ها، ۲) اهلیت طرفین، ۳) موضوع معین که مورد معامله باشد، ۴) مشروعیت جهت معامله."),
    (82, "قراردادی که به صورت صحیح واقع شده باشد بین متعاملین قائم‌مقام قانون است."),
    (83, "عقد محقق می‌شود به قصد انشاء به شرط مقرون بودن به چیزی که دلالت بر قصد کند."),
    (84, "اظهار قصد ممکن است به وسیله عملی که دلالت بر قصد نماید به عمل آید مثل قبض و اقباض و تسلیم ثمن."),
    (85, "اگر طرفین در یک مکان حاضر باشند عقد به ایجاب و قبول شفاهی محقق می‌شود."),
    (86, "اگر کسی کاری را انجام دهد که دلالت بر رضایت به امری نماید آن امر نسبت به او نافذ است."),
    (87, "ایجاب به‌صورتی که مورد قبول واقع نشده باشد ایجاب‌کننده را ملزم نمی‌کند مگر در مواردی که قانون معین کرده است."),
    (88, "ایجاب زمانی مؤثر است که طرف قبول را در زمان مناسب ابراز کند."),
    (89, "اگر قبول به چیزی غیر از آنچه ایجاب شده تعلق گیرد موجب عدم انعقاد عقد است مگر این‌که ایجاب‌کننده قبول نماید."),
    (90, "معامله پس از آن‌که یکی از طرفین ایجاب نماید در صورتی محقق می‌شود که طرف دیگر در زمانی که هر دو در یک مجلس حاضرند قبولی بدهند و بعد از پراکندگی هرگونه ایجاب و قبولی قبل از قبول، هر ایجاب از بین می‌رود."),
    (91, "هرگاه کسی به وسیله نامه یا تلگراف یا پیام کتبی دیگر ایجاب معامله‌ای بکند قبول وقتی محقق می‌شود که قبول‌کننده در موقع مقرر آن را فرستاده باشد و ایجاب‌کننده نیز به آن علم حاصل نماید."),
    (92, "اگر در ایجاب مدتی برای قبول معین شده باشد ایجاب‌کننده در ظرف آن مدت ملتزم باقی می‌ماند."),
    (93, "اگر معامله به وسیله تلفن یا هر وسیله دیگری که طرفین در حکم یک مجلس محسوب می‌شوند واقع گردد در حکم معامله حضوری است."),
    (94, "رضا حاصل می‌شود وقتی که طرفین با کمال اختیار و آزادی اراده به امر توافق نمایند."),
    (95, "اگر کسی به وسیله اکراه و تهدید معامله‌ای بکند آن معامله برای او غیرنافذ و قابل فسخ است."),
    (96, "اکراه عبارت است از تهدید شخص به فعل زیان‌بخش جانی یا مالی که به‌صورت نامشروع باشد."),
    (97, "اگر کسی در نتیجه اکراه معامله‌ای بکند بعد از رفع اکراه می‌تواند معامله را تنفیذ یا فسخ نماید."),
    (98, "اشتباه در مورد خود معامله موجب عدم نفوذ معامله است."),
    (99, "اشتباه در خصوص یکی از دو طرف معامله وقتی موجب عدم نفوذ است که شخصیت طرف علت عمده انعقاد عقد بوده باشد."),
    (100, "اشتباه در مقدار مورد معامله باعث عدم صحت معامله نیست مگر اینکه مقدار با وصفی که ذکر شده تفاوت فاحش داشته باشد."),
    (101, "اشتباه در جهت معامله موجب عدم صحت آن است در صورتی که جهت نامشروع یا دروغ باشد."),
    (102, "تدلیس عبارت است از عملیات یا گفتاری که یکی از طرفین معامله به وسیله آن طرف دیگر را از حقیقت امر منحرف سازد و باعث انجام معامله گردد."),
    (103, "اگر تدلیس موجب اشتباه در معامله شود طرف زیان‌دیده می‌تواند معامله را فسخ نماید."),
    (104, "اگر در معامله غبن فاحش وجود داشته باشد طرف مغبون می‌تواند معامله را فسخ کند."),
    (105, "غبن فاحش در مواردی است که قیمت پرداختی یا تسلیمی به اندازه‌ای کم یا زیاد باشد که در نظر عرف قابل اغماض نباشد."),

    # ---------- ادامه مواد قراردادها ----------
    (106, "معامله فضولی یعنی معامله به وسیله کسی که مالک یا وکیل مالک نیست اما به نام مالک انجام می‌دهد. این نوع معامله با اجازه مالک یا قائم‌مقام او نافذ می‌شود."),
    (107, "معامله فضولی در صورتی نافذ می‌شود که مالک یا قائم‌مقام او آن را صراحتاً یا به‌طور ضمنی تنفیذ کند."),
    (108, "تنفیذ در صورتی مؤثر است که با رضای کامل و بدون اکراه و با اطلاع از تمام اوضاع و احوال حاصل شده باشد."),
    (109, "در معامله فضولی طرف معامله می‌تواند مهلتی برای صاحب مال تعیین کند تا در آن مهلت رضایت یا عدم رضایت خود را اعلان کند و اگر در مهلت سکوت کرد معامله باطل می‌شود."),
    (110, "مالکیت زمین به‌وسیله احیا و حیازت حاصل می‌شود."),

    # ---------- باب ششم – دفتر دوم: در الزاماتی که بدون قرارداد حاصل می‌شود ----------
    (111, "هرگاه کسی به وسیله دیگری مالی را بدون مجوز قانونی به دست آورد و استفاده از آن مستلزم اضرار به دیگری باشد ضامن است."),
    (112, "کسی که در نتیجه عمل دیگری خسارت می‌بیند مستحق جبران آن است."),
    (113, "هرگاه کسی بدون داشتن حق مالی را قبض کند ضامن آن است."),
    (114, "اگر کسی مالی را در نتیجه اشتباه به دیگری بپردازد می‌تواند از کسی که آن را دریافت کرده استرداد نماید."),
    (115, "کسی که به اختیار خود و بدون این‌که مجبور باشد ادای دین دیگری را بکند می‌تواند آن را از مدیون بگیرد."),
    (116, "کسی که مال دیگری را به علت ضرورت و به نفع صاحب مال خرج کند مستحق گرفتن مخارج خود می‌باشد."),
    (117, "در صورت تلف مال دیگری توسط شخص، ضمان قیمت و در صورت نقصان ضمان نقصان وجود دارد."),
    (118, "اگر کسی مال غصبی را از غاصب بگیرد و به مالک برساند غاصب نسبت به مال ضامن نیست."),
    (119, "هرگاه کسی در نتیجه عمل دیگری زیان ببیند عامل آن باید خسارت وارده را جبران نماید."),
]
